∀ (b c : Int) (qr : Int × Int),
  NativeBridge.Incremental.BinaryDivision.zDivStep b c qr =
    if 2 * qr.snd + c < b then (2 * qr.fst, 2 * qr.snd + c) else (2 * qr.fst + 1, 2 * qr.snd + c - b)

∀ (b c : Nat) (qr : Nat × Nat),
  NativeBridge.Incremental.BinaryDivision.divStep b c qr =
    if b ≤ 2 * qr.snd + c then (2 * qr.fst + 1, 2 * qr.snd + c - b) else (2 * qr.fst, 2 * qr.snd + c)
